<?php
namespace App\Http\Controllers\UserArea; use App\Http\Controllers\Controller; use App\Models\{ServiceRequest,ServiceRequestEvent}; use App\Services\Communications\CommunicationService; use Illuminate\Http\Request; use Illuminate\Support\Facades\{DB,Storage}; use Illuminate\Support\Str;
class ServiceRequestController extends Controller {
 public function index(Request $r){$requests=$r->user()->serviceRequests()->with(['booking.property'])->latest()->paginate(10);$bookings=$r->user()->bookings()->whereNotIn('status',['cancelled','completed','no_show'])->latest()->get();return view('user.service-requests.index',compact('requests','bookings'));}
 public function store(Request $r,CommunicationService $com){$d=$r->validate(['booking_id'=>['required','integer'],'type'=>['required','in:concierge,housekeeping,restaurant,airport_transfer,maintenance,general'],'title'=>['required','string','max:160'],'requested_at'=>['nullable','date'],'notes'=>['nullable','string','max:4000'],'details'=>['nullable','array'],'attachment'=>['nullable','image','max:5120']]);$booking=$r->user()->bookings()->find($d['booking_id']);abort_unless($booking,403);try{$sr=DB::transaction(function()use($r,$d,$booking){$path=$r->file('attachment')?->store('service-requests','private');$sr=ServiceRequest::create([...$d,'reference'=>'SR-'.Str::upper(Str::random(10)),'booking_id'=>$booking->id,'user_id'=>$r->user()->id,'attachment_path'=>$path]);ServiceRequestEvent::create(['service_request_id'=>$sr->id,'actor_id'=>$r->user()->id,'to_status'=>'submitted','note'=>'Request submitted','guest_visible'=>true]);return $sr;});$dest=config('azari.service_request_email')?:config('mail.from.address');if($dest)$com->email($dest,'service_request_submitted','New service request '.$sr->reference,view('emails.service-request',compact('sr','booking'))->render(),$booking,$r->user(),$sr);return back()->with('success','Your request has been submitted.');}catch(\Throwable $e){report($e);return back()->withInput()->with('error','Your request could not be submitted. Please try again.');}}
 public function show(Request $r,ServiceRequest $serviceRequest){abort_unless($serviceRequest->user_id===$r->user()->id,403);$serviceRequest->load('booking.property');$events=$serviceRequest->events()->with('actor')->latest()->paginate(10,['*'],'events_page')->withQueryString();return view('user.service-requests.show',compact('serviceRequest','events'));}
}
